import { GeneratedReport } from './types';

/**
 * ReportFormatter provides utilities for exporting, printing, clipboard copying,
 * and stamping emergency operational reports generated by the hybrid AI layer.
 */
export class ReportFormatter {
  /**
   * Builds an ASCII header and footer stamped with metadata verification.
   */
  public static formatWithHeaderAndFooter(report: GeneratedReport): string {
    const divider = '================================================================================';
    const subDivider = '--------------------------------------------------------------------------------';

    const header = [
      divider,
      ` NATIONAL EMERGENCY OPERATIONS CENTRE // HYBRID AI INTELLIGENCE SYSTEM`,
      ` DOCUMENT: ${report.title.toUpperCase()}`,
      ` CLASSIFICATION: OFFICIAL USE ONLY // TACTICAL CRISIS MANAGEMENT`,
      divider,
      ` REPORT ID         : ${report.id}`,
      ` TIMESTAMP         : ${new Date(report.generatedAt).toUTCString()}`,
      ` GENERATED BY      : ${report.providerName}`,
      ` OPERATIONAL MODE  : ${report.mode}`,
      ` REASONING ENGINE  : Classical Expert System (Confidence: ${(report.confidence * 100).toFixed(1)}%)`,
      ` TRIGGERED RULES   : ${report.triggeredRulesCount} Production Rules Verified`,
      ` INFERENCE LATENCY : ${report.generationTimeMs} ms`,
      ` DOCUMENT VERSION  : ${report.version}`,
      subDivider,
      '',
    ].join('\n');

    const footer = [
      '',
      subDivider,
      ` [VERIFICATION STAMP]`,
      ` All operational decisions, threat indices, and resource allocations are computed`,
      ` authoritatively by the Classical Expert System Blackboard. Generative AI is strictly`,
      ` utilized for natural language articulation and report formatting.`,
      divider,
    ].join('\n');

    return `${header}\n${report.content}\n${footer}`;
  }

  /**
   * Triggers a browser download of the report as a .txt file.
   */
  public static downloadAsText(report: GeneratedReport): void {
    const fullText = this.formatWithHeaderAndFooter(report);
    const blob = new Blob([fullText], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    const sanitizedTitle = report.title.replace(/[^a-zA-Z0-9_-]/g, '_');
    const timestampStr = new Date(report.generatedAt).toISOString().replace(/[:.]/g, '-');
    link.href = url;
    link.download = `${sanitizedTitle}_${timestampStr}.txt`;

    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

  /**
   * Copies formatted report text to the system clipboard.
   */
  public static async copyToClipboard(text: string): Promise<boolean> {
    try {
      if (navigator.clipboard && window.isSecureContext) {
        await navigator.clipboard.writeText(text);
        return true;
      } else {
        const textArea = document.createElement('textarea');
        textArea.value = text;
        textArea.style.position = 'fixed';
        textArea.style.left = '-999999px';
        textArea.style.top = '-999999px';
        document.body.appendChild(textArea);
        textArea.focus();
        textArea.select();
        const successful = document.execCommand('copy');
        document.body.removeChild(textArea);
        return successful;
      }
    } catch (err) {
      console.error('[ReportFormatter] Failed to copy to clipboard:', err);
      return false;
    }
  }

  /**
   * Opens the report in a sanitized print window with high-contrast print typography.
   */
  public static printReport(report: GeneratedReport): void {
    const formattedText = this.formatWithHeaderAndFooter(report);
    const printWindow = window.open('', '_blank', 'width=900,height=700');
    if (!printWindow) {
      alert('Pop-up window blocked. Please allow pop-ups to print reports.');
      return;
    }

    const htmlContent = `
      <!DOCTYPE html>
      <html>
        <head>
          <title>${report.title} - Official Emergency Report</title>
          <style>
            @media print {
              @page { margin: 15mm; }
              body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
            }
            body {
              font-family: 'Courier New', Courier, monospace;
              font-size: 11pt;
              line-height: 1.45;
              color: #111827;
              background-color: #ffffff;
              padding: 20px;
              margin: 0;
            }
            pre {
              white-space: pre-wrap;
              word-wrap: break-word;
              margin: 0;
            }
            .header-banner {
              border-bottom: 2px solid #111827;
              padding-bottom: 10px;
              margin-bottom: 20px;
            }
          </style>
        </head>
        <body>
          <pre>${escapeHtml(formattedText)}</pre>
          <script>
            window.onload = function() {
              window.print();
              setTimeout(() => window.close(), 1000);
            };
          </script>
        </body>
      </html>
    `;

    printWindow.document.open();
    printWindow.document.write(htmlContent);
    printWindow.document.close();
  }
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}
